// R15K Arcade – build script of the "device" plugin: generates the allow-* permissions of its
// three commands (into the gitignored permissions/autogenerated/) and links the Android library
// and the Swift package into mobile builds.
const COMMANDS: &[&str] = &["set_immersive", "set_keep_awake", "move_to_background"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .ios_path("ios")
        .build();
}
